<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';require __DIR__.'/UserAccessFixture.php';
$f=new UserAccessFixture(dirname(__DIR__,2));
try{
 $owner=$f->owner();$created=$owner->invite(9101,'password.policy@shlz.ru','Policy fixture');$token=$created['token'];
 foreach(['Abcde1!xy','abcdefghi1!xyz','ABCDEFGHI1!XYZ','Abcdefghij!xyz','Abcdefghi123xy','Abcdefghi1 xyz','Abcdefghi1яxyz','Aa1!яяя','Aa1!'.str_repeat('x',197),"Aa1!xxxx\xffxx",'password.policyA1!','PASSWORD.POLICYa1!']as$password){$before=$f->facts();$r=$owner->activate($token,$password,$password);assertSameValue('invalid_password',$r['status'],'reject missing group/length/encoding/email');assertSameValue($before,$f->facts(),'invalid password leaves token and credential untouched');}
 $before=$f->facts();assertSameValue('invalid_password',$owner->activate($token,'Abcdef1!xy','Abcdef2!xy')['status'],'confirmation match required');assertSameValue($before,$f->facts(),'mismatch no writes');
 $f->start();$guest=[];$form=$f->request('GET','/pilot/activate?token='.$token,[],$guest);assertSameValue(200,$form['status'],'activation page');assertSameValue(2,substr_count($form['body'],'minlength="10"'),'both fields new minimum');assertSameValue(2,substr_count($form['body'],'maxlength="200"'),'both fields preserve maximum');$dom=new DOMDocument();@$dom->loadHTML('<?xml encoding="UTF-8">'.$form['body']);$xp=new DOMXPath($dom);foreach($xp->query('//input[@type="password"]')as$field){$help=$field->getAttribute('aria-describedby');assertSameValue(true,$help!=='','password help linked');$node=$dom->getElementById($help);assertSameValue(true,$node!==null&&str_contains($node->textContent,'спецсимвол'),'linked visible requirement help');}foreach(['строчную','заглавную','цифру','спецсимвол']as$term)assertSameValue(true,str_contains($form['body'],$term),'visible group help '.$term);assertSameValue(false,str_contains($form['body'],'minlength="14"'),'old constraint removed');
 $password='Abcdef1!xy';$response=$f->request('POST','/pilot/activate',['_csrf'=>$f->csrf($form['body']),'token'=>$token,'password'=>$password,'passwordConfirmation'=>$password],$guest);assertSameValue(200,$response['status'],'10-character activation HTTP');assertSameValue(true,str_contains($response['body'],'Учётная запись активирована'),'activation succeeds');$id=$created['userId'];$hash=$f->db->query("SELECT password_hash FROM {$f->p}fm2_pilot_auth_credentials WHERE user_id=$id")->fetch_column();assertSameValue(true,password_verify($password,$hash),'exact accepted password hash');assertSameValue('argon2id',password_get_info($hash)['algoName'],'hash algorithm preserved');assertSameValue(303,$f->login($guest,'password.policy@shlz.ru',$password)['status'],'new password normal login');assertSameValue('invalid',$owner->activate($token,$password,$password)['status'],'used token cannot reset password');
 foreach(['Abcdef0?xy','Aa1!яяяяяя','Aa1!'.str_repeat('x',196),' Abcdef1!xy ']as$i=>$valid){$inv=$owner->invite(9101,'allowed'.$i.'@shlz.ru','Allowed fixture');assertSameValue('activated',$owner->activate($inv['token'],$valid,$valid)['status'],'valid character policy including digit0/punctuation/Unicode/max');$stored=$f->db->query("SELECT password_hash FROM {$f->p}fm2_pilot_auth_credentials WHERE user_id=".(int)$inv['userId'])->fetch_column();assertSameValue(true,password_verify($valid,$stored),'password bytes retained');if(trim($valid)!==$valid){assertSameValue(false,password_verify(trim($valid),$stored),'password not silently trimmed');$spaceCookies=[];assertSameValue(303,$f->login($spaceCookies,'allowed'.$i.'@shlz.ru',$valid)['status'],'exact spaced password logs in');}}
 $existing=[];assertSameValue(303,$f->login($existing)['status'],'existing password without new composition still logs in');
 echo "PASS: activation10/fourgroups, no-write errors, old login, hash and single-use preserved\n";
}finally{$f->close();}
